func TestFortinetCpeDetectionAndEnrichment(t *testing.T) {
	const cveID = "CVE-2023-12345"
	detail := cvemodels.CveDetail{
		CveID: cveID,
		Fortinets: []cvemodels.Fortinet{
			{
				AdvisoryID:      "FG-IR-23-001",
				AdvisoryURL:     "https://www.fortiguard.com/psirt/FG-IR-23-001",
				Title:           "FortiOS advisory",
				Summary:         "FortiOS is affected",
				DetectionMethod: cvemodels.FortinetExactVersionMatch,
				Cvss3:           cvemodels.FortinetCvss3{Cvss3: cvemodels.Cvss3{BaseScore: 9.8, VectorString: "CVSS:3.1/AV:N", BaseSeverity: "CRITICAL"}},
				Cwes:            []cvemodels.FortinetCwe{{CweID: "CWE-79"}},
				References:      []cvemodels.FortinetReference{{Reference: cvemodels.Reference{Link: "https://example.com/reference", Source: "Fortinet"}}},
			},
			{
				AdvisoryID:      "FG-IR-23-002",
				AdvisoryURL:     "https://www.fortiguard.com/psirt/FG-IR-23-002",
				Summary:         "Another FortiOS advisory",
				DetectionMethod: cvemodels.FortinetVendorProductMatch,
			},
		},
	}
	jvnOnly := cvemodels.CveDetail{CveID: "CVE-2023-99999", Jvns: []cvemodels.Jvn{{JvnID: "JVN123"}}}

	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch r.URL.Path {
		case "/cpes":
			_ = json.NewEncoder(w).Encode([]cvemodels.CveDetail{detail, jvnOnly})
		case "/cves/" + cveID:
			_ = json.NewEncoder(w).Encode(detail)
		default:
			http.NotFound(w, r)
		}
	}))
	defer srv.Close()

	cnf := config.GoCveDictConf{VulnDict: config.VulnDict{Type: "http", URL: srv.URL}}
	result := models.ScanResult{ScannedCves: models.VulnInfos{}}
	cpes := []Cpe{{CpeURI: "cpe:/o:fortinet:fortios:4.3.0", UseJVN: false}}
	if err := DetectCpeURIsCves(&result, cpes, cnf, logging.LogOpts{}); err != nil {
		t.Fatal(err)
	}
	if len(result.ScannedCves) != 1 {
		t.Fatalf("detected CVEs = %v, want Fortinet-only CVE", result.ScannedCves)
	}
	vinfo := result.ScannedCves[cveID]
	if !reflect.DeepEqual(vinfo.Confidences, models.Confidences{models.FortinetExactVersionMatch}) {
		t.Errorf("confidence = %v", vinfo.Confidences)
	}
	if !reflect.DeepEqual(vinfo.DistroAdvisories, models.DistroAdvisories{{AdvisoryID: "FG-IR-23-001"}, {AdvisoryID: "FG-IR-23-002"}}) {
		t.Errorf("advisories = %v", vinfo.DistroAdvisories)
	}

	if err := FillCvesWithNvdJvnFortinet(&result, cnf, logging.LogOpts{}); err != nil {
		t.Fatal(err)
	}
	contents := result.ScannedCves[cveID].CveContents[models.Fortinet]
	if len(contents) != 2 || contents[0].SourceLink != detail.Fortinets[0].AdvisoryURL || contents[0].Cvss3Score != 9.8 ||
		!reflect.DeepEqual(contents[0].CweIDs, []string{"CWE-79"}) || len(contents[0].References) != 1 {
		t.Errorf("Fortinet contents = %+v", contents)
	}
}

